    line=lines[i]
    m=re.match(r'^Module ([A-Za-z0-9_]+)\.$', line)
    if not m:
        # outside modules: collect until next Module; but tail preserved raw for now
        out.append((None,line)); i+=1; continue
    mod=m.group(1)
