        if dm:
            names.append(dm.group(1))
            # inductive constructors
            if ln.startswith('Inductive'):
                k2=k+1
                while k2 < len(body):
                    l2=body[k2]
                    cm=re.match(r'^[ \t]*\|\s*([A-Za-z_][A-Za-z0-9_\']*)\b', l2)
